const demo = $('Configure check').first().json.demoCase;
if (demo === 'empty') return [];
if (demo === 'invalid') return [{json:{unexpectedField:'fictional'}}];
if (demo === 'duplicates') return [
  {json:{recordId:'DEMO-001'}}, {json:{recordId:'DEMO-001'}}, {json:{recordId:'DEMO-002'}}
];
if (demo !== 'healthy') throw new Error('Use healthy, empty, invalid, or duplicates for demoCase.');
return [1,2,3].map(i => ({json:{recordId:`DEMO-00${i}`}}));

const config = $('Configure check').first().json;
const minimum = Number(config.minimumItems);
if (!Number.isSafeInteger(minimum) || minimum < 0 || minimum > 1000000000)
  throw new Error('minimumItems must be a non-negative integer, at most 1000000000.');
const field = String(config.recordIdField || '').trim();
if (!field) throw new Error('Set recordIdField to the field identifying a completed output.');
const rows = $input.all().filter(item => Object.keys(item.json || {}).length > 0);
const keys = new Set();
let invalidItems = 0;
for (const item of rows) {
  const value = item.json[field];
  const valid = (typeof value === 'string' && value.trim().length > 0)
    || (typeof value === 'number' && Number.isFinite(value));
  if (!valid) { invalidItems++; continue; }
  keys.add(String(value).trim());
}
const items = keys.size;
const duplicateItems = rows.length - invalidItems - items;
const checkPassed = items >= minimum && invalidItems === 0;
const checkStatus = invalidItems ? 'invalid_output' : items < minimum ? 'below_minimum' : 'healthy';
return [{json:{
  checkPassed, checkStatus, minimumItems:minimum, items, invalidItems, duplicateItems,
  receipt:{eventId:`n8n:${$workflow.id}:${$execution.id}:${$runIndex}`, success:checkPassed,
    items, test:config.testReceipt === true,
    message:`Output check: ${items} distinct IDs; minimum ${minimum}; ${invalidItems} invalid; ${duplicateItems} duplicates.`}
}}];

if ($json.received !== true) throw new Error('The receiver did not confirm this receipt.');
return [{json:{...$('Check completed outputs').first().json,
  receiptAccepted:true, duplicateReceipt:$json.duplicate === true,
  monitorStatus:$json.status || null}}];
